import 'package:flutter/material.dart';import '../../../core/data/astro_repository.dart';import '../../../core/theme/app_theme.dart';import '../../../features/journal/presentation/journal_screen.dart';
class SavedScreen extends StatefulWidget{const SavedScreen({super.key});@override State<SavedScreen> createState()=>_SavedScreenState();}
class _SavedScreenState extends State<SavedScreen>{List<Map<String,Object?>> saved=[],journal=[],history=[];bool loading=true;@override void initState(){super.initState();_load();}
Future<void> _load()async{final r=AstroRepository.instance;saved=await r.saved();journal=await r.journal();history=await r.history();if(mounted)setState(()=>loading=false);}
@override Widget build(BuildContext context)=>DefaultTabController(length:3,child:Scaffold(appBar:AppBar(title:const Text('Your space'),bottom:const TabBar(tabs:[Tab(text:'Favorites'),Tab(text:'Journal'),Tab(text:'History')])),body:loading?const Center(child:CircularProgressIndicator()):TabBarView(children:[saved.isEmpty?_empty('Saved readings will appear here.'):ListView(children:saved.map((r){final title=r['title'] as String? ?? 'Saved item';final body=r['body'] as String? ?? '';return ListTile(leading:const Icon(Icons.bookmark,color:AppTheme.primary),title:Text(title),subtitle:Text(r['sign'] as String? ?? ''),onTap:()=>showDialog(context:context,builder:(_)=>AlertDialog(title:Text(title),content:Text(body))));}).toList()),journal.isEmpty?_empty('Your private reflections stay on this device.'):ListView(children:journal.map((r)=>ListTile(title:Text(r['day'] as String),subtitle:Text(r['body'] as String,maxLines:2,overflow:TextOverflow.ellipsis),onTap:()async{await Navigator.push(context,MaterialPageRoute(builder:(_)=>JournalScreen(prompt:r['prompt'] as String,entry:r)));_load();},trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{await AstroRepository.instance.deleteJournal(r['id'] as String);_load();}))).toList()),history.isEmpty?_empty('Readings you open will be listed here.'):ListView(children:history.map((r)=>ListTile(leading:const Icon(Icons.history),title:Text(r['id'] as String),subtitle:Text(r['viewed_at'] as String))).toList())])));
Widget _empty(String t)=>Center(child:Padding(padding:const EdgeInsets.all(25),child:Text(t,textAlign:TextAlign.center,style:const TextStyle(color:AppTheme.muted))));}
